/* @lc app=leetcode id=3743 lang=kotlin */ class Solution { fun solve(a: IntArray, rf: Int, rl: Int, jm: Int, wrap: Boolean): Long = a.fold(Array(jm + 1) { j -> LongArray(4) { m -> if (j == 0 && m == 3) 0L else Long.MIN_VALUE / 4 } }) { dp, x -> Array(jm + 1) { LongArray(4) { Long.MIN_VALUE / 4 } }.also { nd -> (0..jm).forEach { j -> (0..3).forEach { m -> dp[j][m].let { v -> if (v > Long.MIN_VALUE / 8) (0..3).forEach { s -> (v + (if (s and 1 != 0) x.toLong() else 0L) - (if (s and 2 != 0) x.toLong() else 0L)).let { nv -> (if (j >= 1 && s and m == 0) nd[j].set(m or s, maxOf(nd[j][m or s], nv)) else Unit).let { if (j + 1 <= jm && (j == 0 || (j == 1 && m == rf) || (j >= 2 && m == 3))) nd[j + 1].set(s, maxOf(nd[j + 1][s], nv)) } } } } } } } }.let { dp -> if (wrap) (2..jm).maxOf { dp[it][rl] } else (1..jm).maxOf { dp[it][3] } } fun maximumScore(nums: IntArray, k: Int): Long = maxOf(solve(nums, 3, 3, k, false), (0..3).maxOf { r -> solve(nums, r, 3 xor r, k + 1, true) }) }